"""Public, crawlable product pages and original brand assets. No account access."""
import html
import json
from pathlib import Path
from adapters.catalog import CATALOG,BASE_CATALOG

ROOT='https://catproof.ai'
APP='https://app.catproof.ai'
STATIC=Path(__file__).parent/'brand_static'
ASSETS={
 '/brand-theme.css':('theme.css','text/css; charset=utf-8'),
 '/marketing.css':('marketing.css','text/css; charset=utf-8'),
 '/assets/catproof-mark.svg':('catproof-mark.svg','image/svg+xml'),
 '/assets/catproof-cat.svg':('catproof-cat.svg','image/svg+xml'),
 '/favicon.svg':('catproof-mark.svg','image/svg+xml'),
 '/favicon.ico':('favicon.ico','image/x-icon'),
 '/favicon-32.png':('favicon-32.png','image/png'),
 '/apple-touch-icon.png':('apple-touch-icon.png','image/png'),
 '/assets/icon-192.png':('icon-192.png','image/png'),
 '/assets/icon-512.png':('icon-512.png','image/png'),
 '/assets/social-card.png':('social-card.png','image/png'),
}
PAGES={
 '/':('CatProof | Federated AI Agent Registry & System of Record','Bring AI agent inventories into one system of record. Link source identities, assign accountable owners, and preserve decisions as source metadata changes.'),
 '/connectors':('AI Agent Registry Connectors | CatProof','Explore CatProof’s read-only AI agent connectors, supported inventory scope, authentication requirements, and current validation limits.'),
 '/guides/agent-system-of-record':('What Is an AI Agent System of Record? | CatProof','Learn how an AI agent system of record connects source identities, business owners, lifecycle decisions, and evidence across multiple platforms.'),
}
ICON_LINKS='<link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><meta name="theme-color" content="#143c39">'

def asset(path):
    if path not in ASSETS:return None
    name,mime=ASSETS[path];return (STATIC/name).read_bytes(),mime

def graph(path,title,description):
    organization={'@type':'Organization','@id':ROOT+'/#organization','name':'CatProof','url':ROOT+'/','logo':{'@type':'ImageObject','url':ROOT+'/assets/icon-512.png','width':512,'height':512},'description':'CatProof develops a federated AI agent registry and system of record.'}
    site={'@type':'WebSite','@id':ROOT+'/#website','url':ROOT+'/','name':'CatProof','publisher':{'@id':ROOT+'/#organization'},'inLanguage':'en'}
    page={'@type':'WebPage','@id':ROOT+path+'#page','url':ROOT+path,'name':title,'description':description,'isPartOf':{'@id':ROOT+'/#website'},'inLanguage':'en'}
    entities=[organization,site,page]
    if path=='/':
        entities.append({'@type':'SoftwareApplication','@id':ROOT+'/#application','name':'CatProof','url':ROOT+'/','applicationCategory':'BusinessApplication','operatingSystem':'Web browser','description':description,'publisher':{'@id':ROOT+'/#organization'},'featureList':['Configured read-only agent discovery','Canonical business ownership','Explicit source identity linking','Source freshness and change history','Separate account registries']})
        page['mainEntity']={'@id':ROOT+'/#application'}
    else:
        entities.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'CatProof','item':ROOT+'/'},{'@type':'ListItem','position':2,'name':'Connectors' if path=='/connectors' else 'AI agent system of record','item':ROOT+path}]})
    return json.dumps({'@context':'https://schema.org','@graph':entities},ensure_ascii=False).replace('<','\\u003c')

def shell(path,body,app_origin=APP):
    title,description=PAGES[path];esc=html.escape;app=esc(app_origin or APP,quote=True)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description,quote=True)}"><link rel="canonical" href="{ROOT+path}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:site_name" content="CatProof"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{ROOT+path}"><meta property="og:image" content="{ROOT}/assets/social-card.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="CatProof cat logo and the words Every AI agent. One accountable record."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title,quote=True)}"><meta name="twitter:description" content="{esc(description,quote=True)}"><meta name="twitter:image" content="{ROOT}/assets/social-card.png">{ICON_LINKS}<link rel="stylesheet" href="/account.css"><link rel="stylesheet" href="/marketing.css"><link rel="stylesheet" href="/brand-theme.css"><script type="application/ld+json">{graph(path,title,description)}</script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="marketing-header"><a class="brand" href="/" aria-label="CatProof home"><img src="/assets/catproof-mark.svg" alt="" width="38" height="38"><span>CatProof</span></a><nav aria-label="Main navigation"><a href="/#how-it-works">Product</a><a href="/connectors">Connectors</a><a href="/guides/agent-system-of-record">Guide</a><a href="/demo">Demo</a><a href="{app}/login">Sign in</a><a class="primary" href="{app}/signup">Get started ↗</a></nav></header><main id="main" class="marketing-main">{body.replace('{{APP}}',app)}</main><footer class="marketing-footer"><div><a class="brand" href="/"><img src="/assets/catproof-mark.svg" alt="" width="28" height="28"><span>CatProof</span></a><p>Every agent. Accounted for.</p></div><nav aria-label="Footer"><a href="/connectors">Connector coverage</a><a href="/guides/agent-system-of-record">How the registry works</a><a href="/demo">Fictional demo</a><a href="{app}/signup">Create a registry</a></nav><p class="footer-note">Early access · Read-only source discovery. Registry lifecycle decisions do not start or stop vendor agents. No runtime enforcement or compliance certification is implied.</p></footer></body></html>'''

def home(app_origin):
    body='''<section class="marketing-hero"><div><p class="eyebrow">AI AGENT REGISTRY & SYSTEM OF RECORD</p><h1>Every AI agent.<br><em>One accountable record.</em></h1><p class="hero-copy">CatProof brings configured agent inventories into one federated system of record. Link source identities, name the business owner, and keep your decisions as source metadata changes.</p><div class="cta"><a class="primary" href="{{APP}}/signup">Start your inventory ↗</a><a class="secondary-link" href="/demo">Explore the fictional demo →</a></div><p class="hero-notes">Early access · No credit card · Private registry per account</p></div><div class="cat-stage"><img src="/assets/catproof-cat.svg" alt="An original CatProof cat holding an ownership record beside three source identities" width="480" height="440" fetchpriority="high"><div class="cat-caption"><span class="status-dot"></span>Curious by nature. Accountable by design.</div></div></section>
<section class="definition-block" aria-labelledby="what-catproof"><p class="eyebrow">WHAT IS CATPROOF?</p><h2 id="what-catproof">A home for your agent inventory.<br>A clear answer to “who owns it?”</h2><p>CatProof is an early-access AI agent registry for teams working across multiple platforms. It separates business ownership and lifecycle decisions from vendor metadata, while retaining the source identity and freshness behind each record.</p></section>
<section id="how-it-works" class="product-flow"><div class="section-intro"><p class="eyebrow">FROM SCATTERED TO ACCOUNTED FOR</p><h2>Connect. Assign. Keep the evidence.</h2></div><div class="feature-grid"><article><span class="step-number">01</span><h3>Connect the landscape</h3><p>Read metadata from an authorized, configured source. Keep platform scope, last-seen evidence and refresh failures visible.</p></article><article><span class="step-number">02</span><h3>Name the owner</h3><p>Link source identities to a canonical agent record. Assign the business owner and local lifecycle deliberately.</p></article><article><span class="step-number">03</span><h3>Preserve the decision</h3><p>Refresh observations without overwriting ownership, review notes or lifecycle. Inspect source changes and decisions in history.</p></article></div></section>
<section class="inventory-preview"><div><p class="eyebrow">THE RECORD THAT TRAVELS WITH THE AGENT</p><h2>Two source identities.<br>One business owner.</h2><p>One logical agent may appear in multiple registries. CatProof preserves each source ID while keeping the business record separate.</p><a href="/demo">Try the ownership workflow →</a></div><div class="sample-record"><div class="sample-top"><span>ILLUSTRATIVE RECORD</span><span class="sample-tag">Fictional</span></div><h3>Invoice triage</h3><p>Accountable owner <strong>Jordan Lee · Finance</strong></p><p>Canonical lifecycle <strong>Active</strong></p><div class="sample-sources"><span>Snowflake Cortex</span><span>A2A Agent Card</span></div><small>Source identities linked deliberately. This is demo data.</small></div></section>
<section class="coverage-section"><p class="eyebrow">BUILT FOR A MIXED AGENT ESTATE</p><h2>Your platforms. A common inventory.</h2><div class="platform-pills"><span>Snowflake Cortex Agents</span><span>Microsoft Copilot Studio</span><span>AWS Bedrock Agents</span><span>Google Agent Registry</span><span>A2A Agent Cards</span></div><p>Adapters read configured scope, not every agent in an organization. Authentication, permissions and validation status vary by connector.</p><a href="/connectors">See connector coverage and limitations →</a></section>
<section class="faq-section" aria-labelledby="faq-title"><div><p class="eyebrow">STRAIGHT ANSWERS</p><h2 id="faq-title">Before you connect.</h2><a href="/guides/agent-system-of-record">Read the system-of-record guide →</a></div><div class="faq-list"><details open><summary>What is a federated AI agent registry?</summary><p>A federated AI agent registry reads inventories from configured sources and relates their source identities to common agent records. Source systems remain responsible for their own definitions and runtime state.</p></details><details><summary>Does CatProof control or run agents?</summary><p>No. CatProof reads source metadata and stores local ownership, lifecycle and review decisions. Setting a canonical lifecycle to suspended does not stop the agent in its vendor platform.</p></details><details><summary>Does discovery find every agent automatically?</summary><p>No. Discovery covers the sources, regions, projects and permissions configured for each connection. Agents outside that scope may be absent. Failed refreshes retain prior evidence with a stale indicator.</p></details><details><summary>Can I try it without provider credentials?</summary><p>Yes. The public interactive demo uses fictional data. A new account can also register manual records and connect public A2A or MCP endpoints. Protected providers require authorized credentials provisioned for the registry.</p></details><details><summary>What is included in early access?</summary><p>Personal signup, a separate registry per account, manual agent records, connector configuration, ownership and lifecycle fields, explicit identity links, refresh history, team roles, revocable invitations and session controls. Email verification, password recovery, invitations, SSO and billing are not connected yet.</p></details><details><summary>Are all connectors verified in customer environments?</summary><p>No. The catalog distinguishes implementation and fixture or contract testing from live-account validation. Real coverage must be checked against the authorized tenant and configured scope.</p></details></div></section>
<section class="closing-cta"><div><p class="eyebrow">START SMALL. MAKE OWNERSHIP CLEAR.</p><h2>Give your first agent a proper record.</h2><p>Create an empty private registry, then register an agent or connect an authorized source.</p></div><a class="primary" href="{{APP}}/signup">Create your registry ↗</a></section>'''
    return shell('/',body,app_origin)

def connectors(app_origin):
    cards=[]
    for kind,spec in sorted({**CATALOG,**BASE_CATALOG}.items(),key=lambda item:item[1]['label'].casefold()):
        esc=html.escape
        reference=spec['reference'] if spec['reference'].startswith('https://') else '/guides/agent-system-of-record'
        reference_label='Official API or contract reference ↗' if reference.startswith('https://') else 'Read the registry guide →'
        cards.append('<article class="coverage-card"><p class="eyebrow">'+esc(spec['category'])+'</p><h2>'+esc(spec['label'])+'</h2><p>'+esc(spec['coverage'])+'</p><p class="validation"><strong>Validation:</strong> '+esc(spec['verification'])+'</p><p><strong>Authentication:</strong> '+esc(spec['auth'])+'</p><a href="'+esc(reference,quote=True)+'" rel="noopener" target="_blank">'+reference_label+'</a></article>')
    return shell('/connectors','''<section class="document-hero"><p class="eyebrow">PUBLIC CONNECTOR COVERAGE</p><h1>Connect the sources.<br><em>Know the scope.</em></h1><p>CatProof’s adapters normalize configured source inventories into agent records or related assets. This catalog describes implementation scope; it is not a claim that every provider has been validated in your account.</p><a class="primary" href="{{APP}}/signup">Configure your first connection ↗</a></section><aside class="public-note"><strong>Agents and assets are different.</strong> MCP servers and directory principals are related evidence, not automatically counted as agents. A credential check confirms configuration only; a successful authorized read and comparison with the provider establish live coverage.</aside><div class="coverage-grid">'''+''.join(cards)+'''</div><section class="closing-cta"><div><h2>Bring one authorized source.</h2><p>Start with a narrowly scoped read-only account and compare observed names and IDs with the source platform.</p></div><a class="primary" href="{{APP}}/signup">Create your registry ↗</a></section>''',app_origin)

def guide(app_origin):
    return shell('/guides/agent-system-of-record','''<article class="guide-page"><p class="eyebrow">CATPROOF PRODUCT GUIDE · UPDATED OCTOBER 27, 2026</p><h1>What is an AI agent<br><em>system of record?</em></h1><p class="guide-answer">An AI agent system of record is an authoritative place for an organization’s agent identity, accountable owner, purpose and lifecycle decisions. A federated registry connects those records to observations from multiple source systems, keeping each observation attributable to its source.</p><nav class="guide-toc" aria-label="On this page"><a href="#canonical">Canonical records</a><a href="#federation">Federation</a><a href="#ownership">Ownership</a><a href="#freshness">Freshness</a><a href="#limits">Current limits</a></nav><section id="canonical"><h2>What belongs in the canonical record?</h2><p>In CatProof, the canonical record contains the agent’s name, purpose, business owner, local lifecycle, review state and notes. Source refreshes do not overwrite these decisions. Each linked observation retains its source platform, source ID, source owner, reported status and last-seen evidence.</p></section><section id="federation"><h2>How does federation work?</h2><p>A connector reads an authorized scope and normalizes the observations. An operator deliberately links identities that represent the same logical agent. CatProof does not merge agents merely because their names match. A peer-registry connection reads a compatible canonical catalog through a separate, attributed connection.</p><p>For example, the fictional Invoice triage scenario in the <a href="/demo">interactive demo</a> links a Snowflake identity and an A2A card to one record. That example is not customer evidence or a claim that those platforms synchronize automatically.</p></section><section id="ownership"><h2>Why separate business owners from source owners?</h2><p>A source owner may be a database role, a maker account or a platform team. That is useful evidence, but it may not identify the person accountable for the agent’s business use. CatProof keeps the source owner visible and stores the business owner as a separate local decision.</p></section><section id="freshness"><h2>What does last seen tell you?</h2><p>Last-seen evidence describes when a source observation was collected. It does not certify that an agent is serving traffic, safe or compliant. A failed or paused refresh retains previous evidence as stale. Absence from one successful scoped read does not prove organization-wide deletion.</p></section><section><h2>Which platforms can I connect?</h2><p>The <a href="/connectors">connector catalog</a> lists adapter scope, authentication and validation limits. Examples include Snowflake Cortex Agents, Microsoft Copilot Studio, AWS Bedrock Agents, Google Agent Registry and supplied A2A cards. MCP servers and directory identities remain related assets.</p><ul><li><a href="https://docs.snowflake.com/en/user-guide/snowflake-cortex/cortex-agents-rest-api" rel="noopener">Snowflake Cortex Agent API</a></li><li><a href="https://learn.microsoft.com/en-us/power-platform/admin/inventory-api" rel="noopener">Microsoft Power Platform inventory API</a></li><li><a href="https://docs.aws.amazon.com/bedrock/latest/APIReference/API_agent_ListAgents.html" rel="noopener">AWS Bedrock ListAgents API</a></li><li><a href="https://a2a-protocol.org/dev/specification/agent-card/" rel="noopener">A2A Agent Card specification</a></li></ul></section><section id="limits"><h2>What does CatProof do today?</h2><p>CatProof provides scoped read-only discovery, manual records, explicit identity linking, business ownership, lifecycle and review fields, history and export. Personal accounts have separate registries with owner, editor and viewer roles. Invitations are single-use codes shared by owners; delivery is manual. Protected connector credentials are provisioned per registry during early access.</p><p>CatProof does not invoke agents, enforce runtime permissions or provide compliance certification. Local lifecycle changes do not stop vendor agents. Email verification, emailed password recovery, SSO, email delivery and billing are not connected. Inventory is stored in PostgreSQL with registry isolation. Catalog size, backup operations and sync scheduling still require validation for larger deployments.</p></section><div class="guide-actions"><a class="primary" href="{{APP}}/signup">Start your inventory ↗</a><a href="/demo">Explore the fictional demo →</a></div></article>''',app_origin)

def public_page(path,app_origin=APP):
    if path=='/':return home(app_origin)
    if path=='/connectors':return connectors(app_origin)
    if path=='/guides/agent-system-of-record':return guide(app_origin)
    return None

def discovery_file(path,marketing=True):
    if path=='/robots.txt':
        body='User-agent: *\n'+('Allow: /\nDisallow: /api/\nDisallow: /account/\nDisallow: /login\nDisallow: /signup\nSitemap: '+ROOT+'/sitemap.xml\n' if marketing else 'Disallow: /\n')
        return body.encode(),'text/plain; charset=utf-8'
    if path=='/sitemap.xml':return ('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ROOT+p+'</loc></url>' for p in PAGES)+'</urlset>').encode(),'application/xml; charset=utf-8'
    if path=='/llms.txt':return ('''# CatProof\n\n> CatProof is an early-access federated AI agent registry and system of record.\n\n## Public product information\n- [Product overview](https://catproof.ai/): configured read-only inventory, canonical ownership and source evidence.\n- [Connector coverage](https://catproof.ai/connectors): adapter scope, authentication and validation limitations.\n- [System-of-record guide](https://catproof.ai/guides/agent-system-of-record): definitions, identity linking, freshness and current limits.\n\n## Product facts and limits\nBusiness ownership is separate from source ownership. Identity linking is explicit. Source refreshes preserve local canonical decisions. MCP servers and directory principals are related assets, not automatically agents. Discovery is limited to configured sources and permissions. The interactive demo is fictional. CatProof does not invoke or stop agents, enforce runtime policies or certify compliance. Email verification, password recovery, automated invitation delivery, SSO and billing are not connected. No customer deployments, ROI or search visibility outcomes are claimed.\n\nThe authenticated application is at https://app.catproof.ai/. Private account and registry data are not public documentation.\n''').encode(),'text/plain; charset=utf-8'
    if path=='/site.webmanifest':return json.dumps({'name':'CatProof','short_name':'CatProof','id':'/','start_url':'/','display':'browser','background_color':'#f4f6ed','theme_color':'#143c39','icons':[{'src':'/assets/icon-192.png','sizes':'192x192','type':'image/png'},{'src':'/assets/icon-512.png','sizes':'512x512','type':'image/png'}]}).encode(),'application/manifest+json'
    return None
